/**
 * chemie-raeume.js — renders the per-element learning-room directory grid
 * from /data/chemie-raeume-manifest.json (generated by
 * scripts/generate-chemie-raeume-manifest.mjs). Every element gets its own
 * tile linking to its deep-linkable room (app + optional Hubs room).
 */
(function () {
  'use strict';

  var GROUP_COLORS = {
    alkali: '#FF6B6B',
    alkalineEarth: '#FFA94D',
    transition: '#74B9FF',
    lanthanide: '#D63384',
    actinide: '#4A69BD',
    metal: '#20C997',
    metalloid: '#17A2B8',
    nonmetal: '#FFC107',
    halogen: '#00D9FF',
    nobleGas: '#FFFFFF',
  };

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  function render(manifest) {
    var grid = document.getElementById('chemie-raeume-grid');
    if (!grid) return;
    var elements = (manifest && manifest.elements) || [];
    if (!elements.length) {
      grid.innerHTML = '<p class="text-muted">Keine Elementräume gefunden.</p>';
      return;
    }
    grid.innerHTML = elements
      .map(function (e) {
        var color = GROUP_COLORS[e.group] || '#888888';
        var cls = e.hubRoomUrl ? 'cr-tile' : 'cr-tile no-hub';
        var hub = e.hubRoomUrl ? '<span class="cr-hub">🔗 Hubs</span>' : '';
        return (
          '<a class="' +
          cls +
          '" href="' +
          escapeHtml(e.roomUrl) +
          '"' +
          ' target="_blank" rel="noopener" style="--c:' +
          color +
          '"' +
          ' title="' +
          escapeHtml(e.name + ' – ' + e.group) +
          '">' +
          '<span class="cr-sym">' +
          escapeHtml(e.symbol) +
          '</span>' +
          '<span class="cr-name">' +
          escapeHtml(e.name) +
          '</span>' +
          hub +
          '</a>'
        );
      })
      .join('');
  }

  function load() {
    fetch('/data/chemie-raeume-manifest.json')
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.json();
      })
      .then(render)
      .catch(function (err) {
        var grid = document.getElementById('chemie-raeume-grid');
        if (grid) {
          grid.innerHTML =
            '<p class="text-danger">Elementräume konnten nicht geladen werden: ' +
            escapeHtml(err.message) +
            '</p>';
        }
      });
  }

  if (typeof document !== 'undefined' && typeof fetch === 'function') {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', load);
    } else {
      load();
    }
  }

  window.ChemieRaeume = { render: render, GROUP_COLORS: GROUP_COLORS };
})();
